using System;using System.Drawing;using System.Drawing.Imaging;using System.IO;using System.Linq;using System.Runtime.InteropServices;using System.Text;
internal sealed class EffectSettings {
 public int Brightness=100,Blur=0,Tint=0,Friends=0,Chat=0,Input=0,Header=0,Navigation=0;public string Color="#000000";public int Saturation=100,Contrast=100,ListBlur=0,NavigationBlur=0,InputBlur=0;public string ListColor,NavigationColor,InputColor;
 public string Key{get{return "v2|"+Brightness+"|"+Blur+"|"+Tint+"|"+Color.ToUpperInvariant()+"|"+Friends+"|"+Chat+"|"+Input+"|"+Header+"|"+Navigation+"|"+Saturation+"|"+Contrast+"|"+ListBlur+"|"+NavigationBlur+"|"+InputBlur+"|"+(ListColor??"same")+"|"+(NavigationColor??"same")+"|"+(InputColor??"same");}}
 public bool Original{get{return Saturation==100&&Contrast==100&&ListBlur==0&&NavigationBlur==0&&InputBlur==0&&Brightness==100&&Blur==0&&Tint==0&&Friends==0&&Chat==0&&Input==0&&Header==0&&Navigation==0;}}
 public EffectSettings Copy(){return new EffectSettings{Brightness=Brightness,Blur=Blur,Tint=Tint,Friends=Friends,Chat=Chat,Input=Input,Header=Header,Navigation=Navigation,Color=Color,Saturation=Saturation,Contrast=Contrast,ListBlur=ListBlur,NavigationBlur=NavigationBlur,InputBlur=InputBlur,ListColor=ListColor,NavigationColor=NavigationColor,InputColor=InputColor};}
 public void Validate(){if(Saturation<0||Saturation>150||Contrast<20||Contrast>150||ListBlur<0||ListBlur>30||NavigationBlur<0||NavigationBlur>30||InputBlur<0||InputBlur>30||new[]{ListColor,NavigationColor,InputColor}.Any(c=>c!=null&&!Palette.IsColor(c))||Brightness<20||Brightness>150||Blur<0||Blur>12||Tint<0||Tint>80||Friends<0||Friends>100||Chat<0||Chat>100||Input<0||Input>100||Header<0||Header>100||Navigation<0||Navigation>100||!Palette.IsColor(Color))throw new InvalidDataException("背景处理参数超出范围。");}
}
internal static partial class BackgroundEffects {
 static string Config{get{return AppearanceProfiles.Path("background-effects.txt");}}
 internal static EffectSettings Parse(string text){var v=text.Trim().TrimStart('\uFEFF').Split('|');bool modern=v.Length>0&&v[0]=="v2";if(modern){if(v.Length!=18)throw new InvalidDataException("分层设置格式不完整。");v=v.Skip(1).ToArray();}else if(v.Length!=4&&v.Length!=7&&v.Length!=9&&v.Length!=10)throw new InvalidDataException("分区设置格式不完整。");var s=new EffectSettings{Brightness=int.Parse(v[0]),Blur=int.Parse(v[1]),Tint=int.Parse(v[2]),Color=v[3]};if(v.Length>=7){s.Friends=int.Parse(v[4]);s.Chat=int.Parse(v[5]);s.Input=int.Parse(v[6]);}if(v.Length>=9){s.Header=int.Parse(v[7]);s.Navigation=int.Parse(v[8]);}if(modern){s.Saturation=int.Parse(v[9]);s.Contrast=int.Parse(v[10]);s.ListBlur=int.Parse(v[11]);s.NavigationBlur=int.Parse(v[12]);s.InputBlur=int.Parse(v[13]);s.ListColor=v[14]=="same"?null:v[14];s.NavigationColor=v[15]=="same"?null:v[15];s.InputColor=v[16]=="same"?null:v[16];}else{bool factory=v.Length>=7&&v[0]=="100"&&v[1]=="0"&&v[2]=="0"&&((v[3].ToUpperInvariant()=="#FFFFFF"&&v[4]=="70"&&v[6]=="35")||(v[3].ToUpperInvariant()=="#000000"&&v[4]=="45"&&v[6]=="18"));if(factory||(v.Length==10&&int.Parse(v[9])>0))s.Friends=s.Chat=s.Header=s.Navigation=0;s.Input=0;}s.Validate();return s;}
 public static EffectSettings Load(){try{return Parse(File.ReadAllText(Config));}catch{return new EffectSettings();}}
 public static void Save(EffectSettings s){s=s.Copy();s.Validate();Directory.CreateDirectory(Engine.Store);string tmp=Config+"."+Guid.NewGuid().ToString("N")+".tmp";try{File.WriteAllText(tmp,s.Key,Encoding.UTF8);if(File.Exists(Config))File.Replace(tmp,Config,null);else File.Move(tmp,Config);}finally{if(File.Exists(tmp))File.Delete(tmp);}}
 public static string Prepare(string source){var settings=Load();if(settings.Original)return source;string dir=Path.Combine(Engine.Store,"effects-cache");Directory.CreateDirectory(dir);string key=Engine.Hash(Encoding.UTF8.GetBytes(source+"|"+settings.Key)),dest=Path.Combine(dir,key+".png");if(File.Exists(dest))return dest;using(var im=Image.FromFile(source))using(var output=Transform(im,settings)){string stage=dest+"."+Guid.NewGuid().ToString("N")+".tmp";try{output.Save(stage,ImageFormat.Png);if(!File.Exists(dest))File.Move(stage,dest);}finally{if(File.Exists(stage))File.Delete(stage);}}try{foreach(var f in new DirectoryInfo(dir).GetFiles("*.png").Where(f=>!f.Name.StartsWith("mask-",StringComparison.OrdinalIgnoreCase)&&!f.Name.StartsWith("region-",StringComparison.OrdinalIgnoreCase)).OrderByDescending(f=>f.LastWriteTimeUtc).Skip(24))if(f.FullName!=dest)f.Delete();}catch{}return dest;}
 public static string Mask(string color,int opacity){string dir=Path.Combine(Engine.Store,"effects-cache");Directory.CreateDirectory(dir);string path=Path.Combine(dir,"mask-"+color.Substring(1)+"-"+opacity+".png");if(!File.Exists(path))using(var pixel=new Bitmap(1,1,PixelFormat.Format32bppArgb)){pixel.SetPixel(0,0,Color.FromArgb((int)Math.Round(opacity*255d/100),ColorTranslator.FromHtml(color)));pixel.Save(path,ImageFormat.Png);}return path;}
 internal static void DrawMaterial(Graphics g,RectangleF bounds,string color,int opacity,int region){using(var brush=new SolidBrush(Color.FromArgb((int)Math.Round(Math.Max(0,Math.Min(100,opacity))*2.55),ColorTranslator.FromHtml(color))))g.FillRectangle(brush,bounds);}
 public static Bitmap Transform(Image source,EffectSettings s){s.Validate();var bitmap=new Bitmap(source.Width,source.Height,PixelFormat.Format32bppArgb);using(var g=Graphics.FromImage(bitmap)){g.CompositingMode=System.Drawing.Drawing2D.CompositingMode.SourceCopy;g.DrawImageUnscaled(source,0,0);}if(s.Original)return bitmap;var area=new Rectangle(0,0,bitmap.Width,bitmap.Height);var data=bitmap.LockBits(area,ImageLockMode.ReadWrite,PixelFormat.Format32bppArgb);try{int w=bitmap.Width,h=bitmap.Height;var pixels=new byte[data.Stride*h];Marshal.Copy(data.Scan0,pixels,0,pixels.Length);if(data.Stride!=w*4)throw new InvalidDataException("不支持的背景图像步长。");if(s.Blur>0){int radius=Math.Max(1,(int)Math.Round(s.Blur/1.5));var temporary=new byte[pixels.Length];for(int pass=0;pass<3;pass++){Box(pixels,temporary,w,h,radius,true);Box(temporary,pixels,w,h,radius,false);}}Color tint=ColorTranslator.FromHtml(s.Color);double opacity=s.Tint/100d,brightness=s.Brightness/100d;for(int i=0;i<pixels.Length;i+=4){double grey=.0722*pixels[i]+.7152*pixels[i+1]+.2126*pixels[i+2];for(int channel=0;channel<3;channel++){double c=grey+(pixels[i+channel]-grey)*s.Saturation/100d;c=(c-127.5)*s.Contrast/100d+127.5;double t=channel==0?tint.B:channel==1?tint.G:tint.R;pixels[i+channel]=(byte)Math.Round(Math.Max(0,Math.Min(255,Math.Max(0,Math.Min(255,c*brightness))*(1-opacity)+t*opacity)));}}Marshal.Copy(pixels,0,data.Scan0,pixels.Length);}finally{bitmap.UnlockBits(data);}return bitmap;}
 static byte Adjust(byte c,byte tint,double brightness,double opacity){return (byte)Math.Round(Math.Min(255,c*brightness)*(1-opacity)+tint*opacity);}
 static void Box(byte[] source,byte[] target,int width,int height,int radius,bool horizontal){int lines=horizontal?height:width,length=horizontal?width:height,step=horizontal?4:width*4,divisor=radius*2+1;for(int line=0;line<lines;line++){int origin=horizontal?line*width*4:line*4;for(int channel=0;channel<4;channel++){int sum=0;for(int k=-radius;k<=radius;k++)sum+=source[origin+Math.Max(0,Math.Min(length-1,k))*step+channel];for(int position=0;position<length;position++){target[origin+position*step+channel]=(byte)((sum+divisor/2)/divisor);int remove=Math.Max(0,position-radius),add=Math.Min(length-1,position+radius+1);sum+=source[origin+add*step+channel]-source[origin+remove*step+channel];}}}}
}